SET NOCOUNT ON;
IF DB_NAME() NOT IN(N'WhatsBizERP_QA',N'WhatsBizERP_PROD') THROW 52130,N'Unexpected database for V43 validation.',1;
IF NOT EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'commerce.StorefrontConfigurations') AND name=N'DefaultReturnWindowDays' AND system_type_id=56 AND is_nullable=0) THROW 52131,N'V43 store default return-window column is missing or invalid.',1;
IF NOT EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'master.Products') AND name=N'ReturnPolicyMode' AND system_type_id=167 AND max_length=20 AND is_nullable=0) OR NOT EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'master.Products') AND name=N'ReturnWindowDays' AND system_type_id=56 AND is_nullable=1) THROW 52132,N'V43 product return-policy columns are missing or invalid.',1;
IF NOT EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID(N'commerce.StorefrontConfigurations') AND name=N'DF_StorefrontConfigurations_DefaultReturnWindowDays' AND REPLACE(REPLACE(definition,N'(',N''),N')',N'')=N'7') OR NOT EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID(N'master.Products') AND name=N'DF_Products_ReturnPolicyMode' AND REPLACE(REPLACE(definition,N'(',N''),N')',N'')=N'''INHERIT_DEFAULT''') THROW 52133,N'V43 default constraints are missing or incorrect.',1;
IF NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'master.Products') AND name=N'CK_Products_ReturnPolicyMode' AND is_disabled=0 AND is_not_trusted=0) OR NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'master.Products') AND name=N'CK_Products_ReturnWindowDays' AND is_disabled=0 AND is_not_trusted=0) THROW 52134,N'V43 return-policy constraints are missing, disabled or untrusted.',1;
IF EXISTS(SELECT 1 FROM commerce.StorefrontConfigurations WHERE DefaultReturnWindowDays IS NULL OR DefaultReturnWindowDays<0) OR EXISTS(SELECT 1 FROM master.Products WHERE ReturnPolicyMode IS NULL OR ReturnPolicyMode NOT IN(N'INHERIT_DEFAULT',N'CUSTOM',N'NON_RETURNABLE')) OR EXISTS(SELECT 1 FROM master.Products WHERE ReturnPolicyMode=N'CUSTOM' AND (ReturnWindowDays IS NULL OR ReturnWindowDays<0)) OR EXISTS(SELECT 1 FROM master.Products WHERE ReturnPolicyMode=N'NON_RETURNABLE' AND ReturnWindowDays IS NOT NULL) THROW 52135,N'V43 existing data contains invalid return-policy state.',1;
SELECT N'V43_VALID' AS ValidationResult;
